FItemRow URecordRefDataLibrary::GetItemRow(int32 Key, bool& bFound)
{
    const FItemRow* Found = FRecordRefData::Item().FindByIndex(Key);

    bFound = Found != nullptr;

    // A copy, because Blueprint takes a struct by value and the row belongs to the table.
    // A default one when the key is not there, which is why bFound is not decoration.
    return Found != nullptr ? *Found : FItemRow();
}

int32 URecordRefDataLibrary::GetItemRowCount()
{
    return FRecordRefData::Item().Records().Num();
}

FItemRow URecordRefDataLibrary::GetItemRowAt(int32 Position, bool& bFound)
{
    const TArray<FItemRow>& Rows = FRecordRefData::Item().Records();

    bFound = Rows.IsValidIndex(Position);

    return bFound ? Rows[Position] : FItemRow();
}


