bool URecordRefDataLibrary::ReadAll(const FString& BasePath, const FString& FileExtension)
{
    return FRecordRefData::ReadAll(BasePath, FileExtension);
}

bool FRecordRefData::ReadAll(const FString& BasePath, const FString& FileExtension)
{
    // Read into tables of their own and moved into place at the end. Reading again is a
    // refresh - a patched .pak, a downloaded table - and one that fails on the third file
    // must not leave the first two replaced and the rest as they were.
    FItemTable LoadedItem;

    if (!LoadedItem.Read(FPaths::Combine(BasePath, TEXT("Item") + FileExtension)))
    {
        return false;
    }
    FLoadoutTable LoadedLoadout;

    if (!LoadedLoadout.Read(FPaths::Combine(BasePath, TEXT("Loadout") + FileExtension)))
    {
        return false;
    }
    FHolderTable LoadedHolder;

    if (!LoadedHolder.Read(FPaths::Combine(BasePath, TEXT("Holder") + FileExtension)))
    {
        return false;
    }
    FBagTable LoadedBag;

    if (!LoadedBag.Read(FPaths::Combine(BasePath, TEXT("Bag") + FileExtension)))
    {
        return false;
    }
    FMountTable LoadedMount;

    if (!LoadedMount.Read(FPaths::Combine(BasePath, TEXT("Mount") + FileExtension)))
    {
        return false;
    }
    FClipTable LoadedClip;

    if (!LoadedClip.Read(FPaths::Combine(BasePath, TEXT("Clip") + FileExtension)))
    {
        return false;
    }
    FPoseTable LoadedPose;

    if (!LoadedPose.Read(FPaths::Combine(BasePath, TEXT("Pose") + FileExtension)))
    {
        return false;
    }
    FSealTable LoadedSeal;

    if (!LoadedSeal.Read(FPaths::Combine(BasePath, TEXT("Seal") + FileExtension)))
    {
        return false;
    }
    FBadgeTable LoadedBadge;

    if (!LoadedBadge.Read(FPaths::Combine(BasePath, TEXT("Badge") + FileExtension)))
    {
        return false;
    }
    FKitTable LoadedKit;

    if (!LoadedKit.Read(FPaths::Combine(BasePath, TEXT("Kit") + FileExtension)))
    {
        return false;
    }

    ItemStorage = MoveTemp(LoadedItem);
    LoadoutStorage = MoveTemp(LoadedLoadout);
    HolderStorage = MoveTemp(LoadedHolder);
    BagStorage = MoveTemp(LoadedBag);
    MountStorage = MoveTemp(LoadedMount);
    ClipStorage = MoveTemp(LoadedClip);
    PoseStorage = MoveTemp(LoadedPose);
    SealStorage = MoveTemp(LoadedSeal);
    BadgeStorage = MoveTemp(LoadedBadge);
    KitStorage = MoveTemp(LoadedKit);

    return true;
}
